package mutuelle_backend.controller;
import jakarta.validation.Valid; import java.util.List; import lombok.RequiredArgsConstructor; import mutuelle_backend.dto.*; import mutuelle_backend.service.UserService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/users") @RequiredArgsConstructor @PreAuthorize("hasAuthority('SECTION_SUPER_ADMIN')") public class AdminController { private final UserService users; @GetMapping public List<UserResponse> all(){return users.all();} @PostMapping public ResponseEntity<UserResponse> create(@Valid @RequestBody UserRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(users.create(request));} }
